def histogram(bounds,freq):
 x0=bounds[0];x1=bounds[-1];dens=[f/(b-a) for a,b,f in zip(bounds,bounds[1:],freq)];top=max(dens)*1.2
 px=lambda x:65+500*(x-x0)/(x1-x0);py=lambda y:290-230*y/top
 es=[txt((65,25),'Frequency-density histogram',16),line((65,290),(575,290)),line((65,290),(65,45)),txt((525,330),'value'),txt((5,42),'density',12)]
 for a,b,d in zip(bounds,bounds[1:],dens):es +=[f'<rect x="{px(a):.3f}" y="{py(d):.3f}" width="{px(b)-px(a):.3f}" height="{290-py(d):.3f}" fill="#ccfbf1" stroke="#0f766e" stroke-width="2"/>',txt(((px(a)+px(b))/2-8,py(d)-7),n(d),12)]
 for b in bounds:es +=[txt((px(b)-8,312),b,12)]
 return svg(es)
